local CommemorativeTokenMaker = {}
local PRODUCTS = {
    simple_lead_token = { name = "Preprost svinčev žeton", leadCost = 2, time = 2, cost = 30, beauty = 15, prestige = 2, happiness = 1, description = "Preprost svinčev žeton za spomine." },
    bronze_minted_token = { name = "Bronast kovan žeton", bronzeCost = 2, leadCost = 1, time = 4, cost = 90, beauty = 28, prestige = 5, happiness = 1, description = "Bronast kovan žeton za trgovce." },
    silver_commemorative_coin = { name = "Srebrni spominski kovanec", silverCost = 2, bronzeCost = 1, leadCost = 1, time = 7, cost = 240, beauty = 42, prestige = 12, happiness = 2, description = "Srebrni spominski kovanec za plemiče." },
    gold_commemorative_coin = { name = "Zlati spominski kovanec", goldCost = 2, silverCost = 1, bronzeCost = 1, leadCost = 1, time = 11, cost = 600, beauty = 58, prestige = 22, happiness = 3, description = "Zlati spominski kovanec za visoke plemiče." },
    jewel_set_medallion = { name = "Draguljasta medaljon", goldCost = 2, silverCost = 1, bronzeCost = 1, jewelCost = 1, leadCost = 1, time = 15, cost = 1400, beauty = 75, prestige = 36, happiness = 5, description = "Medaljon z draguljem za visoko plemstvo." },
    royal_grand_commemorative = { name = "Kraljevski veliki spominski kovanec", goldCost = 3, silverCost = 2, bronzeCost = 1, jewelCost = 2, pearlCost = 2, leadCost = 1, time = 22, cost = 3200, beauty = 92, prestige = 60, happiness = 12, description = "Veliki kraljevski spominski kovanec z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    token_workshop = { name = "Žetonska delavnica", cost = { gold = 220, wood = 100, stone = 120, lead = 6 }, upkeep = 5, qualityBonus = 5 },
    minting_loft = { name = "Kovinska podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, bronze = 6 }, upkeep = 20, qualityBonus = 18 },
    master_minter_atelier = { name = "Mojstrski kovinarski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_mint_palace = { name = "Kraljevska kovinska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
CommemorativeTokenMaker.leadStock = 14; CommemorativeTokenMaker.bronzeStock = 12; CommemorativeTokenMaker.silverStock = 8; CommemorativeTokenMaker.goldStock = 6; CommemorativeTokenMaker.jewelStock = 4; CommemorativeTokenMaker.pearlStock = 4
CommemorativeTokenMaker.productStock = {}; CommemorativeTokenMaker.buildings = {}; CommemorativeTokenMaker.maker = nil; CommemorativeTokenMaker.activeMaking = {}; CommemorativeTokenMaker.totalProducts = 0; CommemorativeTokenMaker.dayTimer = 0
function CommemorativeTokenMaker.init() CommemorativeTokenMaker.leadStock=14; CommemorativeTokenMaker.bronzeStock=12; CommemorativeTokenMaker.silverStock=8; CommemorativeTokenMaker.goldStock=6; CommemorativeTokenMaker.jewelStock=4; CommemorativeTokenMaker.pearlStock=4; CommemorativeTokenMaker.productStock={}; CommemorativeTokenMaker.buildings={}; CommemorativeTokenMaker.maker=nil; CommemorativeTokenMaker.activeMaking={}; CommemorativeTokenMaker.totalProducts=0; CommemorativeTokenMaker.dayTimer=0; print("[CommemorativeTokenMaker] Royal Commemorative Token Maker System initialized (6 products, 4 buildings)") end
function CommemorativeTokenMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CommemorativeTokenMaker.maker={name=n or ("Žetonar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žetonar najet: %s (spretnost: %d)",CommemorativeTokenMaker.maker.name,s),"success") end; return true end
function CommemorativeTokenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CommemorativeTokenMaker.build(id) local ok,e=CommemorativeTokenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CommemorativeTokenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CommemorativeTokenMaker.getQualityBonus() local b=0; for _,bd in ipairs(CommemorativeTokenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CommemorativeTokenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leadCost and CommemorativeTokenMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.bronzeCost and CommemorativeTokenMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and CommemorativeTokenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CommemorativeTokenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CommemorativeTokenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CommemorativeTokenMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CommemorativeTokenMaker.buildings==0 then return false,"Potrebna žetonska delavnica" end; if not CommemorativeTokenMaker.maker then return false,"Potreben žetonar" end; return true end
function CommemorativeTokenMaker.make(pt,qty) qty=qty or 1; local ok,e=CommemorativeTokenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leadCost then CommemorativeTokenMaker.leadStock=CommemorativeTokenMaker.leadStock-d.leadCost*qty end; if d.bronzeCost then CommemorativeTokenMaker.bronzeStock=CommemorativeTokenMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then CommemorativeTokenMaker.silverStock=CommemorativeTokenMaker.silverStock-d.silverCost*qty end; if d.goldCost then CommemorativeTokenMaker.goldStock=CommemorativeTokenMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CommemorativeTokenMaker.jewelStock=CommemorativeTokenMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CommemorativeTokenMaker.pearlStock=CommemorativeTokenMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CommemorativeTokenMaker.maker then t=math.max(1,t-math.floor(CommemorativeTokenMaker.maker.skill/13)) end; table.insert(CommemorativeTokenMaker.activeMaking,{id="token_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CommemorativeTokenMaker.completeMaking(m) local q=1.0+(CommemorativeTokenMaker.getQualityBonus()/100); if CommemorativeTokenMaker.maker then q=q+(CommemorativeTokenMaker.maker.skill/140) end; q=math.min(2.5,q); CommemorativeTokenMaker.productStock[m.productType]=(CommemorativeTokenMaker.productStock[m.productType] or 0)+m.quantity; CommemorativeTokenMaker.totalProducts=CommemorativeTokenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CommemorativeTokenMaker.maker then CommemorativeTokenMaker.maker.itemsMade=CommemorativeTokenMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CommemorativeTokenMaker.maker.skill=math.min(100,CommemorativeTokenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žeton izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"token.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function CommemorativeTokenMaker.update(dt) if not _G.state then return end; CommemorativeTokenMaker.dayTimer=CommemorativeTokenMaker.dayTimer+dt; if CommemorativeTokenMaker.dayTimer>=30 then CommemorativeTokenMaker.dayTimer=0; for i=#CommemorativeTokenMaker.activeMaking,1,-1 do local m=CommemorativeTokenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CommemorativeTokenMaker.completeMaking(m); table.remove(CommemorativeTokenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CommemorativeTokenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CommemorativeTokenMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CommemorativeTokenMaker.getStats() return {leadStock=CommemorativeTokenMaker.leadStock,bronzeStock=CommemorativeTokenMaker.bronzeStock,silverStock=CommemorativeTokenMaker.silverStock,goldStock=CommemorativeTokenMaker.goldStock,jewelStock=CommemorativeTokenMaker.jewelStock,pearlStock=CommemorativeTokenMaker.pearlStock,productStock=CommemorativeTokenMaker.productStock,numBuildings=#CommemorativeTokenMaker.buildings,hasMaker=CommemorativeTokenMaker.maker~=nil,makerName=CommemorativeTokenMaker.maker and CommemorativeTokenMaker.maker.name or "—",makerSkill=CommemorativeTokenMaker.maker and CommemorativeTokenMaker.maker.skill or 0,activeMaking=#CommemorativeTokenMaker.activeMaking,totalProducts=CommemorativeTokenMaker.totalProducts} end
return CommemorativeTokenMaker
